import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    left = [-1] * n
    right = [n] * n
    st = []
    for i in range(n):
        while st and a[st[-1]] >= a[i]:
            right[st.pop()] = i
        left[i] = st[-1] if st else -1
        st.append(i)
    ans = [0] * (n + 2)
    for i in range(n):
        ln = right[i] - left[i] - 1
        if a[i] > ans[ln]:
            ans[ln] = a[i]
    for k in range(n - 1, 0, -1):
        if ans[k + 1] > ans[k]:
            ans[k] = ans[k + 1]
    print(' '.join(map(str, ans[1:n + 1])))

main()

