    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([10**9]), fmt([5, 5, 5, 5]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([2, 1]), fmt([1, 2])]
    for n in (2, 3, 4, 6, 8, 10, 15, 20, 30):
        for _ in range(3):
            hi = rng.choice([3, 10, 1000])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt(list(range(1, n + 1))))
    tests.append(fmt(list(range(n, 0, -1))))
    tests.append(fmt([rng.randint(1, 5) for _ in range(n)]))
    tests.append(fmt([10**9] * n))
    tests.append(fmt([(i % 1000) * 1000 + 1 for i in range(n)]))
    return tests

